  public ArrayList BuildPluginCenterItems() {
    ArrayList<PluginCenterItem> items = new ArrayList<>();
    PluginCenterItem item = null;
    item.id = "builtin.light.ai";
    item.name = "AI接口";
    item.version = "1.0.0";
    item.author = "Light 内置";
    item.description = "内置 AI 对话与网页模式，属于插件，需安装。";
    item.kind = "内置功能";
    item.enabled = m_aiEnabled;
    item.builtin = true;
    item.canToggle = true;
    item.canOpenFolder = false;
    item.canReload = false;
    items.add(item);
    if (g_PluginManager) {
      var records = g_PluginManager.GetPluginRecords();
      for (var record_ : records) {
        PluginCenterItem item = null;
        item.id = AnsiToWide(record_.id);
        item.name = AnsiToWide((record_.name.isEmpty() ? record_.id : record_.name));
        item.version = AnsiToWide((record_.version.isEmpty() ? "1.0.0" : record_.version));
        item.author = AnsiToWide((record_.author.isEmpty() ? "未知作者" : record_.author));
        item.description = AnsiToWide(record_.description);
        item.path = AnsiToWide(record_.path);
        if (record_.isApiPlugin) {
          item.kind = "API 指令集";
        }
        else {
          if (record_.isGuiPlugin) {
            item.kind = "GUI 插件";
          }
          else {
            item.kind = "原生插件";
          }
        }
        item.enabled = record_.enabled;
        item.builtin = false;
        item.canToggle = true;
        item.canOpenFolder = !(record_.path.isEmpty());
        item.canReload = !(record_.path.isEmpty());
        items.add(item);
      }
    }
    for (long i = 0; (i < m_jsPlugins.size()); ++i) {
      if (((((int) i) == m_aiIndex) || !(m_jsPlugins[i]))) {
        continue;
      }
      var plug = m_jsPlugins[i];
      PluginCenterItem item = null;
      item.id = plug.GetId();
      item.name = plug.GetName();
      item.version = plug.GetVersion();
      item.author = "JS 扩展";
      item.description = "基于 QuickJS 的界面扩展";
      item.path = plug.GetFolderPath();
      item.kind = "JS 扩展";
      item.enabled = !(IsJSPluginDisabled(item.id));
      item.builtin = false;
      item.canToggle = true;
      item.canOpenFolder = !(item.path.isEmpty());
      item.canReload = true;
      items.add(item);
    }
    return items;
  }
