  public String InstallExtensionFromCrx(String crxPath) {
    if ((GetFileAttributesW(null) == INVALID_FILE_ATTRIBUTES)) {
      return "";
    }
    String fileName = crxPath;
    long p = fileName.find_last_of("\\/");
    if ((p != wstring.npos)) {
      fileName = fileName.substr((p + 1));
    }
    long dot = fileName.find_last_of('.');
    if ((dot != wstring.npos)) {
      fileName = fileName.substr(0, dot);
    }
    if (fileName.isEmpty()) {
      fileName = "extension";
    }
    String crxDir = GetCacheSubDir("crx");
    String wCrxDir = AnsiToWide(crxDir);
    String zipPath = (((wCrxDir + "\\") + fileName) + ".zip");
    if (!(CrxStripper_WriteZip(crxPath, zipPath))) {
      DeleteFileW(null);
      return "";
    }
    String extRoot = GetCacheSubDir("Extensions");
    String wExtRoot = AnsiToWide(extRoot);
    String destDir = ((wExtRoot + "\\") + fileName);
    if (m_commandHandler) {
      String cmd = "unzip \"";
      cmd += WideToUtf8(zipPath);
      cmd += "\" \"";
      cmd += WideToUtf8(destDir);
      cmd += "\"";
      m_commandHandler(cmd);
    }
    else {
      DeleteFileW(null);
      return "";
    }
    if (!(WaitForManifest(destDir, 30000))) {
      DeleteFileW(null);
      return "";
    }
    DeleteFileW(null);
    return destDir;
  }
  public void StartCrxWatcher() {
    if (m_crxWatcherRunning) {
      return;
    }
    m_crxWatcherRunning = true;
    m_crxWatcherThread = thread(() -> {      ArrayList<String> watchDirs = new ArrayList<>();
      String a = GetCacheSubDir("crx");
      String w = AnsiToWide(a);
      SHCreateDirectoryExW(null, null, null);
      watchDirs.add(w);
      PWSTR p = null;
      if ((SUCCEEDED(SHGetKnownFolderPath(FOLDERID_Downloads, 0, null, p)) && p)) {
        watchDirs.add(p);
        CoTaskMemFree(p);
      }
      char up = new char[]{0};
      if (GetEnvironmentVariableW("USERPROFILE", up, 260)) {
        String fb = (String.valueOf(up) + "\\Downloads");
        if ((GetFileAttributesW(null) != INVALID_FILE_ATTRIBUTES)) {
          boolean dup = false;
          for (var d : watchDirs) {
            if ((_wcsicmp(null, null) == 0)) {
              dup = true;
              break;
            }
          }
          if (!(dup)) {
            watchDirs.add(fb);
          }
        }
      }
      while (m_crxWatcherRunning) {
        for (var wDir : watchDirs) {
          if (!(m_crxWatcherRunning)) {
            break;
          }
          String pattern = (wDir + "\\*.crx");
          WIN32_FIND_DATAW fd = null;
          long hFind = FindFirstFileW(null, fd);
          if ((hFind == -(1))) {
            continue;
          }
          do {
            if ((fd.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY)) {
              continue;
            }
            String fname = fd.cFileName;
            String full = ((wDir + "\\") + fname);
            WIN32_FILE_ATTRIBUTE_DATA fad = null;
            if (!(GetFileAttributesExW(null, GetFileExInfoStandard, fad))) {
              continue;
            }
            long size = (((((long) fad.nFileSizeHigh) << 32)) | fad.nFileSizeLow);
            if ((size <= 0)) {
              continue;
            }
            boolean stable = false;
            lock_guard<Object> lock = new lock_guard<Object>(m_crxMutex);
            var probe = m_crxProbes[fname];
            boolean sizeSame = ((probe.size == size));
            boolean timeSame = (((probe.mtime.dwLowDateTime == fad.ftLastWriteTime.dwLowDateTime)) && ((probe.mtime.dwHighDateTime == fad.ftLastWriteTime.dwHighDateTime)));
            if ((sizeSame && timeSame)) {
              probe.stableCount++;
            }
            else {
              probe.size = size;
              probe.mtime = fad.ftLastWriteTime;
              probe.stableCount = 0;
            }
            if ((probe.stableCount >= 2)) {
              stable = true;
            }
            if (!(stable)) {
              continue;
            }
            String pPath = new String(full);
            if ((m_hWnd && IsWindow(m_hWnd))) {
              PostMessageW(m_hWnd, WM_YXGUI_CRX_DOWNLOADED, 0, ((long) pPath));
            }
            else {
              delete pPath = null;
            }
          } while (FindNextFileW(hFind, fd));
          FindClose(hFind);
        }
        for (int i = 0; ((i < 20) && m_crxWatcherRunning); i++) {
          Sleep(100);
        }
      }          });
  }
