  public void HandleDownloadedCrx(String crxPath) {
    String crx = crxPath;
    String fname = crx;
    long p = fname.find_last_of("\\/");
    if ((p != wstring.npos)) {
      fname = fname.substr((p + 1));
    }
    lock_guard<Object> lock = new lock_guard<Object>(m_crxMutex);
    if ((m_crxSeenFiles.count(fname) > 0)) {
      return;
    }
    m_crxSeenFiles.insert(fname);
    thread(() -> {      String crxDirA = GetCacheSubDir("crx");
      String wCrxDir = AnsiToWide(crxDirA);
      SHCreateDirectoryExW(null, null, null);
      String localCopy = crx;
      if ((crx.find(wCrxDir) == wstring.npos)) {
        String target = ((wCrxDir + "\\") + fname);
        if (MoveFileW(null, null)) {
          localCopy = target;
        }
      }
      String dest = InstallExtensionFromCrx(localCopy);
      if (dest.isEmpty()) {
        lock_guard<Object> lock = new lock_guard<Object>(m_crxMutex);
        m_crxSeenFiles.erase(fname);
        var probe = m_crxProbes[fname];
        probe.retryCount++;
        probe.stableCount = 0;
        DeleteFileW(null);
        return;
      }
      DeleteFileW(null);
      if ((localCopy != crx)) {
        DeleteFileW(null);
      }
      String pDest = new String(dest);
      if ((m_hWnd && IsWindow(m_hWnd))) {
        if (!(PostMessageW(m_hWnd, WM_YXGUI_ADD_EXTENSION_TO_PROFILE, 0, ((long) pDest)))) {
          delete pDest = null;
        }
      }
      else {
        delete pDest = null;
      }        }).detach();
  }
