  public void AppendConsoleText(String text) {
    if ((!(m_hConsoleEdit) || !(IsWindow(m_hConsoleEdit)))) {
      return;
    }
    String crlf = "";
    crlf.reserve((text.length() + 8));
    for (long i = 0; (i < text.length()); i++) {
      char c = text.charAt(i);
      if ((c == '\r')) {
        continue;
      }
      if ((c == '\n')) {
        crlf += "\r\n";
      }
      else {
        crlf += c;
      }
    }
    if (crlf.isEmpty()) {
      return;
    }
    String wtext = AnsiToWide(crlf);
    CHARFORMAT2W cf = new CHARFORMAT2W[]{};
    cf.cbSize = 0;
    cf.dwMask = CFM_COLOR;
    cf.crTextColor = ((((186) | (((198) << 8))) | (((216) << 16))));
    int textLen = GetWindowTextLengthW(m_hConsoleEdit);
    SendMessageW(m_hConsoleEdit, EM_SETSEL, textLen, textLen);
    SendMessageW(m_hConsoleEdit, EM_SETCHARFORMAT, SCF_SELECTION, ((long) cf));
    SendMessageW(m_hConsoleEdit, EM_REPLACESEL, false, ((long) null));
    SendMessageW(m_hConsoleEdit, EM_SCROLLCARET, 0, 0);
  }
  public void OnWindowClose() {
    StopCrxWatcher();
    UnloadJSPlugins();
    if (m_popupWebView) {
      m_popupWebView.Release();
      m_popupWebView = null;
    }
    if (m_popupController) {
      m_popupController.Close();
      m_popupController.Release();
      m_popupController = null;
    }
    if (m_popupEnv) {
      m_popupEnv.Release();
      m_popupEnv = null;
    }
    m_popupReady = false;
    if (m_optionsWebView) {
      m_optionsWebView.Release();
      m_optionsWebView = null;
    }
    if (m_optionsController) {
      m_optionsController.Close();
      m_optionsController.Release();
      m_optionsController = null;
    }
    if (m_optionsEnv) {
      m_optionsEnv.Release();
      m_optionsEnv = null;
    }
    for (var t : m_tabs) {
      if (t.controller) {
        t.controller.Close();
        t.controller.Release();
        t.controller = null;
      }
      if (t.webView) {
        t.webView.Release();
        t.webView = null;
      }
      if (t.hostWnd) {
        DestroyWindow(t.hostWnd);
        t.hostWnd = null;
      }
    }
    m_tabs.clear();
    if (m_webViewEnv) {
      m_webViewEnv.Release();
      m_webViewEnv = null;
    }
    m_webViewReady = false;
  }
