  public static String ExtractExtIdFromUrl(String rawUrl) {
    String url = rawUrl;
    while ((!(url.isEmpty()) && (((url.front() == ' ') || (url.front() == '\t'))))) {
      url.erase(0, 1);
    }
    while ((!(url.isEmpty()) && (((((url.back() == ' ') || (url.back() == '\t')) || (url.back() == '\r')) || (url.back() == '\n'))))) {
      url.remove(url.size() - 1);
    }
    if (url.isEmpty()) {
      return "";
    }
    long q = url.find_first_of("?#");
    if ((q != wstring.npos)) {
      url = url.substr(0, q);
    }
    while ((!(url.isEmpty()) && (url.back() == '/'))) {
      url.remove(url.size() - 1);
    }
    long slash = url.find_last_of('/');
    if ((slash == wstring.npos)) {
      return "";
    }
    String id = url.substr((slash + 1));
    if (((id.length() < 20) || (id.length() > 64))) {
      return "";
    }
    for (char c : id) {
      if (!((((((c >= 'a') && (c <= 'z'))) || (((c >= '0') && (c <= '9'))))))) {
        return "";
      }
    }
    return id;
  }
