  public static boolean CrxStripper_WriteZip(String crxPath, String outZipPath) {
    ifstream in = new ifstream(crxPath, ios.binary);
    if (!(in.is_open())) {
      return false;
    }
    char head = new char[]{0};
    in.read(((String) head), 16);
    if ((in.gcount() < 12)) {
      return false;
    }
    if (((((head[0] != 'C') || (head[1] != 'r')) || (head[2] != '2')) || (head[3] != '4'))) {
      return false;
    }
    int version = (((head[4] | ((head[5] << 8))) | ((head[6] << 16))) | ((head[7] << 24)));
    long zipOffset = 0;
    if ((version == 2)) {
      if ((in.gcount() < 16)) {
        return false;
      }
      int pk = (((head[8] | ((head[9] << 8))) | ((head[10] << 16))) | ((head[11] << 24)));
      int sk = (((head[12] | ((head[13] << 8))) | ((head[14] << 16))) | ((head[15] << 24)));
      zipOffset = ((16 + pk) + sk);
    }
    else {
      if ((version == 3)) {
        int hs = (((head[8] | ((head[9] << 8))) | ((head[10] << 16))) | ((head[11] << 24)));
        zipOffset = (12 + hs);
      }
      else {
        return false;
      }
    }
    in.seekg(((streamoff) zipOffset), ios.beg);
    if (!(in.good())) {
      return false;
    }
    ofstream out = new ofstream(outZipPath, (ios.binary | ios.trunc));
    if (!(out.is_open())) {
      return false;
    }
    char buf = '\0';
    while (in) {
      in.read(buf, 0);
      streamsize n = in.gcount();
      if ((n <= 0)) {
        break;
      }
      out.write(buf, n);
    }
    return true;
  }
