  public static String JsonExtractString(String json, String key) {
    String pat = (("\"" + key) + "\"");
    long p = json.indexOf(pat);
    if ((p == string.npos)) {
      return "";
    }
    p += pat.length();
    while (((p < json.length()) && ((((json.charAt(p) == ' ') || (json.charAt(p) == ':')) || (json.charAt(p) == '\t'))))) {
      p++;
    }
    if (((p >= json.length()) || (json.charAt(p) != '"'))) {
      return "";
    }
    p++;
    long end = p;
    while (((end < json.length()) && (json.charAt(end) != '"'))) {
      if ((json.charAt(end) == '\\')) {
        end++;
      }
      end++;
    }
    return AnsiToWide(json.substring(p, (end - p)));
  }
