  public static String Help_GetHelpText(String programDir) {
    String registryPath = (programDir + HELP_REGISTRY_RELATIVE);
    String data = Help_ReadRegistryFile(registryPath);
    if (data.isEmpty()) {
      return ("注册表异常 - 无法读取注册表文件\r\n\r\n路径: " + registryPath);
    }
    long pos = 0;
    ArrayList<String> path = new ArrayList<>(java.util.Arrays.asList("HKEY_LOCAL_MACHINE", "xbyx", "xcyx"));
    for (var node : path) {
      pos = data.indexOf(("NODE:" + node), pos);
      if ((pos == string.npos)) {
        return "未找到路径节点";
      }
    }
    long helpDirPos = data.indexOf("NODE:help\nISKEY:1", pos);
    if ((helpDirPos == string.npos)) {
      helpDirPos = data.indexOf("NODE:help\r\nISKEY:1", pos);
    }
    if ((helpDirPos == string.npos)) {
      long childrenPos = data.indexOf("CHILDREN:1", pos);
      while ((childrenPos != string.npos)) {
        long searchStart = (((childrenPos > 50)) ? (childrenPos - 50) : 0);
        if ((searchStart < pos)) {
          searchStart = pos;
        }
        long helpPos = data.rfind("NODE:help", childrenPos);
        if (((helpPos != string.npos) && (helpPos >= searchStart))) {
          helpDirPos = helpPos;
          break;
        }
        childrenPos = data.indexOf("CHILDREN:1", (childrenPos + 10));
      }
    }
    if ((helpDirPos == string.npos)) {
      return "未找到帮助目录节点";
    }
    long childHelpPos = data.indexOf("NODE:help", (helpDirPos + 1));
    if ((childHelpPos == string.npos)) {
      return "未找到子节点 help";
    }
    long valuePos = data.indexOf("VALUE:", childHelpPos);
    if ((valuePos == string.npos)) {
      return "未找到 VALUE";
    }
    valuePos += 6;
    long endPos = data.indexOf("\n", valuePos);
    String helpValue = (((endPos == string.npos)) ? data.substring(valuePos) : data.substring(valuePos, (endPos - valuePos)));
    long p = 0;
    while ((((p = helpValue.indexOf("\\n", p))) != string.npos)) {
      helpValue.replace(p, 2, "\r\n");
      p += 2;
    }
    return helpValue;
  }
  public static void Help_Populate(long hRichEdit, String programDir) {
    if (!(hRichEdit)) {
      return;
    }
    String helpText = Help_GetHelpText(programDir);
    ArrayList<String> lines = new ArrayList<>();
    String current = "";
    for (char c : helpText) {
      if ((c == '\n')) {
        if ((!(current.isEmpty()) && (current.back() == '\r'))) {
          current.remove(current.size() - 1);
        }
        lines.add(current);
        current.clear();
      }
      else {
        current += c;
      }
    }
    if (!(current.isEmpty())) {
      lines.add(current);
    }
    SetWindowTextW(hRichEdit, "");
    CHARFORMAT2W cf = new CHARFORMAT2W[]{};
    cf.cbSize = 0;
    cf.dwMask = CFM_COLOR;
    cf.crTextColor = ((((30) | (((30) << 8))) | (((30) << 16))));
    SendMessageW(hRichEdit, EM_SETCHARFORMAT, SCF_ALL, ((long) cf));
    for (var line : lines) {
      int textLen = GetWindowTextLengthW(hRichEdit);
      SendMessageW(hRichEdit, EM_SETSEL, textLen, textLen);
      if (line.isEmpty()) {
        SendMessageW(hRichEdit, EM_REPLACESEL, false, ((long) "\r\n"));
        continue;
      }
      String wline = AnsiToWide(line);
      wline += "\r\n";
      SendMessageW(hRichEdit, EM_REPLACESEL, false, ((long) null));
    }
    SendMessageW(hRichEdit, EM_SETSEL, 0, 0);
    SendMessageW(hRichEdit, EM_SCROLLCARET, 0, 0);
  }
