  public static String ReadJsonStrField(String text, String key) {
    String pat = (("\"" + key) + "\"");
    long pos = text.find(pat);
    if ((pos == wstring.npos)) {
      return "";
    }
    long colon = text.find(':', (pos + pat.size()));
    if ((colon == wstring.npos)) {
      return "";
    }
    long q1 = text.find('"', (colon + 1));
    if ((q1 == wstring.npos)) {
      return "";
    }
    long q2 = text.find('"', (q1 + 1));
    if ((q2 == wstring.npos)) {
      return "";
    }
    return text.substr((q1 + 1), ((q2 - q1) - 1));
  }
  public static String FindLivelyCover(String livelyDir) {
    if ((livelyDir.isEmpty() || !(fs.is_directory(livelyDir)))) {
      return "";
    }
    String proj = (livelyDir + "\\project.json");
    if (fs.exists(proj)) {
      wifstream in = new wifstream(proj, ios.binary);
      if (in) {
        wstringstream ss = null;
        ss << in.rdbuf();
        String text = ss.str();
        String file = ReadJsonStrField(text, "file");
        if (!(file.isEmpty())) {
          String p = ((livelyDir + "\\") + file);
          if (fs.exists(p)) {
            String ext = fs.path(file).extension().wstring();
            if ((IsImageExt(ext) || IsVideoExt(ext))) {
              return p;
            }
          }
        }
        String prev = ReadJsonStrField(text, "preview");
        if (prev.isEmpty()) {
          prev = ReadJsonStrField(text, "thumbs");
        }
        if (!(prev.isEmpty())) {
          String p = ((livelyDir + "\\") + prev);
          if ((fs.exists(p) && IsImageExt(fs.path(prev).extension().wstring()))) {
            return p;
          }
        }
      }
    }
    try {
      for (var e : fs.directory_iterator(livelyDir)) {
        if (!(e.is_regular_file())) {
          continue;
        }
        String ext = e.path().extension().wstring();
        if (IsImageExt(ext)) {
          return e.path().wstring();
        }
      }
    }
    catch (Throwable __any) {
    }
    return "";
  }
